import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'
import bcrypt from 'bcryptjs'

export async function POST(request: NextRequest) {
  try {
    const body = await request.json()
    const {
      firstName,
      secondName,
      thirdName,
      lastName,
      phone,
      location,
      nationalId,
      licenseNumber,
      licenseExpiryDate,
      password,
    } = body

    if (
      !firstName || !secondName || !thirdName || !lastName ||
      !phone || !location || !nationalId || !licenseNumber ||
      !licenseExpiryDate || !password
    ) {
      return NextResponse.json({ error: 'جميع الحقول مطلوبة' }, { status: 400 })
    }

    if (!/^7\d{8}$/.test(phone)) {
      return NextResponse.json({ error: 'رقم الهاتف يجب أن يبدأ بـ 7 ويتكون من 9 أرقام' }, { status: 400 })
    }

    const existingPhone = await db.nurse.findUnique({ where: { phone } })
    if (existingPhone) {
      return NextResponse.json({ error: 'رقم الهاتف مسجل بالفعل' }, { status: 400 })
    }

    const existingNationalId = await db.nurse.findUnique({ where: { nationalId } })
    if (existingNationalId) {
      return NextResponse.json({ error: 'الرقم الوطني مسجل بالفعل' }, { status: 400 })
    }

    const existingLicense = await db.nurse.findUnique({ where: { licenseNumber } })
    if (existingLicense) {
      return NextResponse.json({ error: 'رقم المزاولة مسجل بالفعل' }, { status: 400 })
    }

    const hashedPassword = await bcrypt.hash(password, 10)
    const nurse = await db.nurse.create({
      data: {
        firstName,
        secondName,
        thirdName,
        lastName,
        phone,
        location,
        nationalId,
        licenseNumber,
        licenseExpiryDate,
        password: hashedPassword,
        status: 'pending',
      },
      select: {
        id: true,
        firstName: true,
        secondName: true,
        thirdName: true,
        lastName: true,
        phone: true,
        location: true,
        status: true,
      },
    })

    return NextResponse.json(nurse)
  } catch (error) {
    return NextResponse.json({ error: 'حدث خطأ في الخادم' }, { status: 500 })
  }
}
